import re, pathlib

NEW = """
<p>در این شب‌گفت، از دردی می‌گویم که نامش در هیچ دفتر درمانی نیامده: «خماریِ درمان». آن سنگینیِ پس از بینش؛ آن صبحِ تلخی که پرده کنار می‌رود و آدمی با حقیقتِ خویش روبه‌رو می‌شود. بزرگانِ ما این حال را بی‌نام نگذاشته‌اند؛ مولانا می‌فرماید: «آتش است این بانگ نای و نیست باد / هر که این آتش ندارد نیست باد.» دردِ آگاهی، آتش است؛ و بی‌آن، نی تنها باد است.</p>
<p>پارسنگِ نما، آن ویترینِ روشن است که رهگذر می‌بیند؛ اما پارسنگِ واقعی، اتاقِ تاریکی است که در آن آدمی بارِ خویش را زمین می‌گذارد. درمان، وعدهٔ آسایشِ بی‌درد نمی‌دهد؛ وعده می‌دهد که درد دیگر بی‌معنا نماند. فرقِ درمانِ عوام و درمانِ خواص در همین است: نخستین تسکین می‌خواهد و دومی، حقیقت.</p>
<p>مراجعی پرسید: پس این سنگینی تا کی؟ گفتم: تا آن دم که اندیشه جانشینِ نقاب شود. مولانا چه خوش سرود: «ای برادر تو همان اندیشه‌ای / مابقی تو استخوان و ریشه‌ای.» تا اندیشهٔ تو از جنسِ ترس باشد، استخوان‌هایت بار می‌کشند؛ چون اندیشه از جنسِ خرد شد، همان استخوان‌ها ستون می‌شوند.</p>
<p>و پایانِ این خماری، نه خندهٔ بی‌غم، که وقار است؛ همان حالتی که فردوسی بزرگ می‌فرماید: «خرد رهنمای و خرد دلگشای / خرد دست گیرد در هر دو سرای.» درمانِ بالینی نیز جز این نیست: دست‌گیریِ خرد از آدمی، در سرایِ درون و سرایِ رابطه.</p>
<p>شب بخیر، خوشه‌چین. فردا چراغ‌ها را نه برای نما، که برای سنگ روشن می‌کنیم؛ که پارسنگ پیش از آنکه نامِ کلینیک باشد، نامِ یک سوگند است: سوگند به اینکه حقیقت، هرچند تلخ، شریف‌تر از هر نقاب است.</p>
"""

p = pathlib.Path("blog/shabgoft-03/index.html")
html = p.read_text(encoding="utf-8")
html = re.sub(r'(<div class="content">).*?(</div>)',
              lambda m: m.group(1) + NEW.strip() + "\n        " + m.group(2),
              html, count=1, flags=re.S)
p.write_text(html, encoding="utf-8")
print("shabgoft-03 rewritten")